"""Book commands: init, db, serve, account, tx, query, export, journal, import, profile, rules."""
import os

from ..csvimport import parse_profile
from ..dates import format_date
from ..errors import NotFoundError, TallybookError
from ..export import money_to_dict, transaction_to_dict, transactions_to_csv, transactions_to_json
from ..journal import JournalError, format_journal, format_transaction, parse_journal
from ..rules import parse_rules
from ..storage import LATEST_VERSION, Store
from .framework import CliError, UsageError, command, parse_int
from .support import (
    POSTING_ALIASES,
    POSTING_OPTION,
    TX_FIELD_OPTIONS,
    account_dict,
    build_transaction,
    date_option,
    money_list_text,
    optional_date,
    print_table,
    print_transactions,
    whole_number,
)

# ------------------------------------------------------------------ book


@command("init", "create the book, or migrate an older one")
def cmd_init(ctx, a):
    path = ctx.db_path
    if not os.path.exists(path):
        Store.open(path, create=True).close()
        ctx.line("created %s (version %d)" % (path, LATEST_VERSION))
        return
    with Store.open(path, create=False) as store:
        before = store.version
        if before == LATEST_VERSION:
            ctx.line("%s is up to date (version %d)" % (path, LATEST_VERSION))
            return
        store.migrate()
        ctx.line("migrated %s from version %d to %d" % (path, before, store.version))


@command("db version", "print the schema version of the book")
def cmd_db_version(ctx, a):
    with ctx.open_store(gate=False) as store:
        ctx.line(str(store.version))


@command("db migrate", "bring an older book up to the current schema")
def cmd_db_migrate(ctx, a):
    with ctx.open_store(gate=False) as store:
        applied = store.migrate()
        if not applied:
            ctx.line("database is up to date (version %d)" % store.version)
        for n in applied:
            ctx.line("applied version %d" % n)


@command("db info", "path, schema version and row counts of the book", flags=("--json",))
def cmd_db_info(ctx, a):
    with ctx.open_store() as store:
        info = store.info()
    if a.flag("--json"):
        ctx.json(info)
        return
    for key in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.line("%s: %s" % (key, info[key]))


@command("db check", "look for damage in the book (exit 1 when there is some)")
def cmd_db_check(ctx, a):
    with ctx.open_store() as store:
        problems = store.check()
    if not problems:
        ctx.line("ok")
        return 0
    for problem in problems:
        ctx.line(problem)
    return 1


@command("db backup", "copy the book to a new file", args="DEST")
def cmd_db_backup(ctx, a):
    dest = a.args[0]
    with ctx.open_store() as store:
        store.backup(dest)
    ctx.line("backed up to %s" % dest)


@command(
    "serve",
    "serve the book over HTTP",
    options={"--host": "HOST", "--port": "N"},
)
def cmd_serve(ctx, a):
    host = a.get("--host", "127.0.0.1")
    port = parse_int(a.get("--port", "8765"), "port")
    if port > 65535:
        raise CliError("invalid port '%s': the largest is 65535" % a.get("--port"))
    ctx.open_store().close()
    from ..api.server import serve

    return serve(ctx.db_path, host=host, port=port, today=ctx._today) or 0


# --------------------------------------------------------------- accounts


@command(
    "account add",
    "add an account",
    args="PATH",
    options={"--currency": "CUR", "--open": "DATE", "--note": "TEXT"},
)
def cmd_account_add(ctx, a):
    opened = optional_date(a, "--open")
    with ctx.open_store() as store:
        acct = store.add_account(a.args[0], currency=a.get("--currency"), opened=opened, note=a.get("--note", ""))
    ctx.line("added account %s" % acct.path)


@command(
    "account list",
    "list the accounts",
    options={"--type": "TYPE", "--under": "PATH", "--currency": "CUR"},
    flags=("--open-only", "--json"),
)
def cmd_account_list(ctx, a):
    with ctx.open_store() as store:
        accounts = store.accounts(
            type=a.get("--type"),
            under=a.get("--under"),
            currency=a.get("--currency"),
            include_closed=not a.flag("--open-only"),
        )
    if a.flag("--json"):
        ctx.json([account_dict(x) for x in accounts])
        return
    rows = [
        [
            x.path,
            x.type,
            x.currency or "",
            "" if x.opened is None else format_date(x.opened),
            "" if x.closed is None else format_date(x.closed),
            x.note,
        ]
        for x in accounts
    ]
    print_table(ctx, ["Account", "Type", "Currency", "Opened", "Closed", "Note"], rows, "llllll")


@command("account show", "show one account and its balance", args="PATH", flags=("--json",))
def cmd_account_show(ctx, a):
    with ctx.open_store() as store:
        acct = store.get_account(a.args[0])
        balance = store.ledger().balance(acct.path)
    monies = [balance[c] for c in sorted(balance)]
    if a.flag("--json"):
        data = account_dict(acct)
        data["balance"] = [money_to_dict(m) for m in monies]
        ctx.json(data)
        return
    ctx.line("path: %s" % acct.path)
    ctx.line("type: %s" % acct.type)
    ctx.line("currency: %s" % (acct.currency or "any"))
    ctx.line("opened: %s" % ("none" if acct.opened is None else format_date(acct.opened)))
    ctx.line("closed: %s" % ("none" if acct.closed is None else format_date(acct.closed)))
    ctx.line(("note: %s" % acct.note).rstrip(" ") if acct.note else "note:")
    ctx.line("balance: %s" % (money_list_text(monies) if monies else "none"))


@command("account close", "close an account", args="PATH", options={"--on": "DATE"})
def cmd_account_close(ctx, a):
    on = date_option(a, "--on", ctx.today)
    with ctx.open_store() as store:
        acct = store.close_account(a.args[0], on)
    ctx.line("closed account %s on %s" % (acct.path, format_date(on)))


# ----------------------------------------------------------- transactions


@command(
    "tx add",
    "add a transaction",
    args="PAYEE",
    options=dict(TX_FIELD_OPTIONS, **{"--date": "DATE"}, **POSTING_OPTION),
    flags=("--json",),
    repeat=("--tag", "--posting"),
    aliases=POSTING_ALIASES,
)
def cmd_tx_add(ctx, a):
    on = date_option(a, "--date", ctx.today)
    tx = build_transaction(a, on, a.args[0])
    with ctx.open_store() as store:
        stored = store.add_transaction(tx)
    if a.flag("--json"):
        ctx.json(transaction_to_dict(stored))
    else:
        ctx.line("added transaction %d" % stored.id)


def _listing(ctx, a, query):
    limit = whole_number(a, "--limit", "limit")
    offset = whole_number(a, "--offset", "offset")
    with ctx.open_store() as store:
        txs = store.transactions(query, limit=limit, offset=offset or 0)
    print_transactions(ctx, txs, a.flag("--json"))


@command(
    "tx list",
    "list transactions",
    options={"--query": "QUERY", "--limit": "N", "--offset": "N"},
    flags=("--json",),
)
def cmd_tx_list(ctx, a):
    _listing(ctx, a, a.get("--query"))


@command("tx show", "show one transaction", args="ID", flags=("--json",))
def cmd_tx_show(ctx, a):
    tx_id = parse_int(a.args[0], "transaction id")
    with ctx.open_store() as store:
        tx = store.get_transaction(tx_id)
    if a.flag("--json"):
        ctx.json(transaction_to_dict(tx))
        return
    ctx.line("; id %d" % tx.id)
    ctx.write(format_transaction(tx))


@command("tx delete", "delete a transaction", args="ID")
def cmd_tx_delete(ctx, a):
    tx_id = parse_int(a.args[0], "transaction id")
    with ctx.open_store() as store:
        store.delete_transaction(tx_id)
    ctx.line("deleted transaction %d" % tx_id)


@command(
    "query",
    "find transactions with a query",
    args="QUERY",
    options={"--limit": "N", "--offset": "N"},
    flags=("--json", "--count"),
)
def cmd_query(ctx, a):
    if a.flag("--count"):
        whole_number(a, "--limit", "limit")
        whole_number(a, "--offset", "offset")
        with ctx.open_store() as store:
            ctx.line(str(store.count_transactions(a.args[0])))
        return
    _listing(ctx, a, a.args[0])


# ---------------------------------------------------------- export/journal

_FORMATS = ("csv", "json", "journal")


def _journal_text(store):
    return format_journal(store.journal())


@command("export", "export transactions as csv, json or journal", options={"--format": "FORMAT", "--query": "QUERY"})
def cmd_export(ctx, a):
    fmt = a.get("--format", "csv")
    if fmt not in _FORMATS:
        raise CliError("invalid format '%s': expected csv, json or journal" % fmt)
    query = a.get("--query")
    if fmt == "journal" and query is not None:
        raise CliError("the journal format exports the whole book and takes no --query")
    with ctx.open_store() as store:
        if fmt == "journal":
            ctx.write(_journal_text(store))
        elif fmt == "csv":
            ctx.write(transactions_to_csv(store.transactions(query)))
        else:
            ctx.write(transactions_to_json(store.transactions(query)))


@command("journal export", "write the whole book as journal text")
def cmd_journal_export(ctx, a):
    with ctx.open_store() as store:
        ctx.write(_journal_text(store))


@command("journal import", "add the contents of a journal file", args="FILE")
def cmd_journal_import(ctx, a):
    text, label = ctx.read_text(a.args[0])
    try:
        journal = parse_journal(text)
    except JournalError as e:
        raise CliError("%s: %s" % (label, e.message)) from None
    with ctx.open_store() as store:
        store.load_journal(journal)
    ctx.line(
        "imported %d accounts, %d rates, %d transactions"
        % (len(journal.accounts), len(journal.rates), len(journal.transactions))
    )


# ------------------------------------------------------ bank statements


@command(
    "import",
    "import a bank statement (CSV)",
    args="FILE",
    options={"--profile": "NAME", "--profile-file": "FILE"},
    flags=("--no-rules",),
)
def cmd_import(ctx, a):
    name, pfile = a.get("--profile"), a.get("--profile-file")
    if (name is None) == (pfile is None):
        raise UsageError("give exactly one of --profile and --profile-file")
    text, _ = ctx.read_text(a.args[0])
    if pfile is not None:
        profile = parse_profile(ctx.read_text(pfile)[0])
    with ctx.open_store() as store:
        if name is not None:
            profile = parse_profile(store.profile_text(name))
        outcome = store.import_csv(text, profile, apply_rules=not a.flag("--no-rules"))
    if outcome.errors:
        raise CliError(
            "%d rows could not be imported, nothing was imported" % len(outcome.errors),
            ["row %s: %s" % (row, message) for row, message in outcome.errors],
        )
    ctx.line("imported %d transactions, %d duplicates" % (len(outcome.added), len(outcome.duplicates)))


@command("profile add", "store an import profile", args="NAME FILE")
def cmd_profile_add(ctx, a):
    name, file = a.args
    text, _ = ctx.read_text(file)
    with ctx.open_store() as store:
        store.set_profile(name, text)
    ctx.line("stored profile %s" % name)


@command("profile list", "list the stored profiles", flags=("--json",))
def cmd_profile_list(ctx, a):
    with ctx.open_store() as store:
        names = store.profiles()
    if a.flag("--json"):
        ctx.json(names)
    for n in names if not a.flag("--json") else ():
        ctx.line(n)


def _with_final_newline(text):
    return text if not text or text.endswith("\n") else text + "\n"


@command("profile show", "print a stored profile", args="NAME")
def cmd_profile_show(ctx, a):
    with ctx.open_store() as store:
        text = store.profile_text(a.args[0])
    ctx.write(_with_final_newline(text))


@command("profile remove", "remove a stored profile", args="NAME")
def cmd_profile_remove(ctx, a):
    with ctx.open_store() as store:
        store.remove_profile(a.args[0])
    ctx.line("removed profile %s" % a.args[0])


@command("rules set", "store the categorisation rules of a file", args="FILE")
def cmd_rules_set(ctx, a):
    text, _ = ctx.read_text(a.args[0])
    count = len(parse_rules(text))
    with ctx.open_store() as store:
        store.set_rules(text)
    ctx.line("stored %d rules" % count)


@command("rules show", "print the stored rules")
def cmd_rules_show(ctx, a):
    with ctx.open_store() as store:
        text = store.rules_text()
    ctx.write(_with_final_newline(text))


from . import commands_money, commands_report  # noqa: E402,F401  (register their commands)

