"""Reports: trial balance, balance sheet, income statement, cash flow, register."""
from ..dates import Period
from ..reports import balance_sheet, cashflow, income_statement, register, render_text, trial_balance
from .framework import command
from .support import month_of, optional_date


def _show(ctx, a, report):
    if a.flag("--json"):
        ctx.json(report)
    else:
        ctx.write(render_text(report))


def _period(ctx, a):
    text = a.get("--period")
    return month_of(ctx.today) if text is None else Period.parse(text)


@command("report trial-balance", "the trial balance", options={"--as-of": "DATE"}, flags=("--json",))
def cmd_report_trial_balance(ctx, a):
    as_of = optional_date(a, "--as-of")
    with ctx.open_store() as store:
        report = trial_balance(store.ledger(), as_of)
    _show(ctx, a, report)


@command(
    "report balance-sheet",
    "the balance sheet",
    options={"--as-of": "DATE", "--convert": "CUR"},
    flags=("--json",),
)
def cmd_report_balance_sheet(ctx, a):
    as_of = optional_date(a, "--as-of") or ctx.today
    with ctx.open_store() as store:
        report = balance_sheet(store.ledger(), as_of, a.get("--convert"), ctx.today)
    _show(ctx, a, report)


@command(
    "report income-statement",
    "the income statement",
    options={"--period": "PERIOD", "--convert": "CUR"},
    flags=("--json",),
)
def cmd_report_income_statement(ctx, a):
    period = _period(ctx, a)
    with ctx.open_store() as store:
        report = income_statement(store.ledger(), period, a.get("--convert"))
    _show(ctx, a, report)


@command("report cashflow", "the cash flow", options={"--period": "PERIOD"}, flags=("--json",))
def cmd_report_cashflow(ctx, a):
    period = _period(ctx, a)
    with ctx.open_store() as store:
        report = cashflow(store.ledger(), period)
    _show(ctx, a, report)


@command(
    "report register",
    "the postings of one account with a running balance",
    args="ACCOUNT",
    options={"--period": "PERIOD"},
    flags=("--rollup", "--json"),
)
def cmd_report_register(ctx, a):
    text = a.get("--period")
    period = None if text is None else Period.parse(text)
    with ctx.open_store() as store:
        report = register(store.ledger(), a.args[0], period, a.flag("--rollup"))
    _show(ctx, a, report)

